CREATE TABLE operational_assets (id INTEGER PRIMARY KEY AUTOINCREMENT,company_id BIGINT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,mine_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('TAILINGS_DAM','LICENSE','DRONE_SURVEY')),name TEXT NOT NULL,status TEXT NOT NULL,due_at TEXT,geometry TEXT,metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,company_id),FOREIGN KEY(mine_id,company_id) REFERENCES mines(id,company_id) ON DELETE CASCADE);
CREATE TABLE exploration_records (id INTEGER PRIMARY KEY AUTOINCREMENT,company_id BIGINT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,mine_id BIGINT NOT NULL,monitoring_area_id BIGINT,sample_code TEXT NOT NULL,record_type TEXT NOT NULL CHECK(record_type IN ('SAMPLE','DRILLHOLE')),lithology TEXT,depth_m DOUBLE PRECISION,grade_gpt DOUBLE PRECISION,geometry TEXT,metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,company_id),FOREIGN KEY(mine_id,company_id) REFERENCES mines(id,company_id) ON DELETE CASCADE,FOREIGN KEY(monitoring_area_id,company_id) REFERENCES monitoring_areas(id,company_id) ON DELETE SET NULL);
CREATE INDEX operational_assets_tenant_idx ON operational_assets(company_id,kind,due_at);
CREATE INDEX exploration_records_tenant_idx ON exploration_records(company_id,mine_id,record_type);
